 using SquadPlaces.Data;
 using SquadPlaces.Data.Models;
 using SquadPlaces.Api.Endpoints.Services;

 namespace SquadPlaces.Api.Endpoints;

 /// <summary>
 /// Extension method for mapping all API endpoints (14 total).
